  @override
  String patientOutageMessage(String facilityContactNumber) {
    return 'ആശുപത്രി സംവിധാനങ്ങൾ താൽക്കാലികമായി ലഭ്യമല്ല. ഇവിടെ കാണിക്കുന്ന വിവരങ്ങൾ നേരത്തെ സംരക്ഷിച്ചതാണ് — ഓരോ പേജിലെയും \'അവസാനം പുതുക്കിയത്\' സമയം പരിശോധിക്കുക. സേവനം പുനഃസ്ഥാപിക്കുന്നതുവരെ പുതിയ ബുക്കിംഗുകൾ, റദ്ദാക്കലുകൾ, മെഡിക്കൽ അഭ്യർത്ഥനകൾ എന്നിവ താൽക്കാലികമായി നിർത്തിയിരിക്കുന്നു. അടിയന്തര ആവശ്യങ്ങൾക്ക് ആശുപത്രിയെ $facilityContactNumber എന്ന നമ്പറിൽ നേരിട്ട് ബന്ധപ്പെടുക. അത്യാഹിതത്തിൽ നിങ്ങളുടെ പ്രാദേശിക അടിയന്തര നമ്പറിൽ വിളിക്കുകയോ നേരിട്ട് എമർജൻസി വിഭാഗത്തിലേക്ക് വരികയോ ചെയ്യുക.';
  }

